// --- sheet challenge with auto-check ---
function solFill(col, r0, r1, f){ const o = {}; for(let r = r0; r <= r1; r++) o[col + r] = XL.shift(f, r - r0, 0); return o; }
function autoSheet(cells, sol, need, names){
  return s => { const ref = new XL.Sheet({...cells, ...sol}, {cols:12, rows:30, names: names || {}});
    const keys = Object.keys(sol);
    for(const a of keys){ const want = ref.value(a), got = s.value(a), isF = String(sol[a]).startsWith('=');
      if(isF && !s.formulaOf(a)) return `${a} needs a formula (start with =).`;
      if(XL.isErr(got)) return `${a} shows ${got}. Check the formula.`;
      const ok = typeof want === 'number' ? (typeof got === 'number' && Math.abs(got - want) < Math.max(0.011, Math.abs(want) * 1e-6)) : String(got) === String(want);
      if(!ok) return `${a} shows "${XL.fmt(got)}" but should be "${XL.fmt(want)}".`; }
    if(need && !keys.some(a => need.test((s.formulaOf(a) || '').toUpperCase()))) return 'Right answer, but use the function named in the task. That is the skill being practised.';
    return true; };
}
function XS(o){ const sol = o.fill ? {...(o.sol || {}), ...solFill(...o.fill)} : o.sol; const cells = o.cells;
  let mc = 1, mr = 1; Object.keys({...cells, ...sol}).forEach(a => { const p = XL.parseRef(a); mc = Math.max(mc, p.c); mr = Math.max(mr, p.r); });
  return { type:'sheet', title:o.t, s:o.s, task:o.task, cells, cols:Math.max(mc, o.cols || 0), rows:mr + 1, select:o.select || Object.keys(sol)[0], names:o.names, goalseek:o.goalseek, k:o.k, solution:sol, hint:o.h, check:o.check || autoSheet(cells, sol, o.need, o.names) }; }
const XQ = (q, opts, a, why, k, s) => ({ type:'quiz', q, opts, a, why, k, s });
const XO = (title, task, items, k, s) => ({ type:'order', title, task, items, k, s });
function XP(t, s, task, cfg, k, src){ return { type:'pivot', src: src || 'clinic', title:t, s, task, k, solution:cfg,
  check:c => c.rows.join() === cfg.rows.join() && c.cols.join() === (cfg.cols || []).join() && c.val === cfg.val && c.agg === cfg.agg ? true : `Rows: ${cfg.rows.join(', ')}${(cfg.cols || []).length ? ' · Columns: ' + cfg.cols.join(', ') : ''} · Values: ${cfg.agg} of ${cfg.val}.` }; }
function XC(t, s, task, types, axis, k, src, value){ return { type:'chart', src: src || 'clinic', value, title:t, s, task, k, solution:{type:types[0], axis},
  check:c => c.axis !== axis ? `Put ${axis} on the axis.` : types.includes(c.type) ? true : `A ${types.join(' or ')} chart fits this question best.` }; }
function XTB(t, s, task, want, k){ return { type:'table', src:'clinic', title:t, s, task, k, solution:want,
  check:st => { if(want.sort && !(st.sort && st.sort.col === want.sort.col && st.sort.dir === want.sort.dir)) return `Sort ${want.sort.col} ${want.sort.dir === 'desc' ? 'largest/Z first' : 'smallest/A first'} (use the ▾ on the header).`;
    if(want.filter){ for(const c in want.filter){ const f = (st.filter || {})[c]; if(!f || f.slice().sort().join() !== want.filter[c].slice().sort().join()) return `Filter ${c} to show only: ${want.filter[c].join(', ')}.`; } }
    if(want.cf && !(st.cf && st.cf.col === want.cf.col && st.cf.op === want.cf.op && String(st.cf.val) === String(want.cf.val))) return `Conditional formatting: ${want.cf.col} ${want.cf.op === '>' ? 'greater than' : want.cf.op === '<' ? 'less than' : 'equals'} ${want.cf.val}.`;
    return true; } }; }
const STORY_STEP = o => ({ type:'story', ...o });

